const SPOTS = 'button,.btn,a.btn,summary,.tool i,.mode,.opt,label>b';
const SIZE  = 'width="1em" height="1em" viewBox="0 0 24 24" fill="none" ' +
              'stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"';

const RE = new RegExp('[' + Object.keys(ICONS).join('') + ']', 'gu');

function swapIn(el){
  if(el.dataset && el.dataset.noico !== undefined) return;
  const walk = document.createTreeWalker(el, NodeFilter.SHOW_TEXT);
  const hits = [];
  let n;
  while((n = walk.nextNode())){
    if(n.parentNode && n.parentNode.closest && n.parentNode.closest('svg')) continue;
    RE.lastIndex = 0;
    if(RE.test(n.nodeValue)) hits.push(n);
  }
  hits.forEach(node => {
    const frag = document.createDocumentFragment();
    let last = 0;
    RE.lastIndex = 0;
    let m;
    while((m = RE.exec(node.nodeValue))){
      if(m.index > last) frag.appendChild(document.createTextNode(node.nodeValue.slice(last, m.index)));
      const art = ICONS[m[0]];
      if(!art){ frag.appendChild(document.createTextNode(m[0])); last = m.index + m[0].length; continue; }
      const span = document.createElement('span');
      span.className = 'ico';
      span.setAttribute('aria-hidden', 'true');
      span.innerHTML = '<svg ' + SIZE + '>' + art + '</svg>';
      frag.appendChild(span);
      last = m.index + m[0].length;
    }
    if(last < node.nodeValue.length) frag.appendChild(document.createTextNode(node.nodeValue.slice(last)));
    node.parentNode.replaceChild(frag, node);
  });
}

function sweep(root){
  if(!root || root.nodeType !== 1) return;
  if(root.matches && root.matches(SPOTS)) swapIn(root);
  const list = root.querySelectorAll ? root.querySelectorAll(SPOTS) : [];
  list.forEach(swapIn);
}

function start(){
  sweep(document.body);
  new MutationObserver(ms => {
    ms.forEach(m => {
      m.addedNodes.forEach(n => {
        /* 字だけ 入れかえられた ときは、その 入れものを 見なおす */
        if(n.nodeType === 3){ if(m.target && m.target.nodeType === 1) sweep(m.target); }
        else sweep(n);
      });
    });
  }).observe(document.body, { childList: true, subtree: true });
}

if(document.readyState === 'loading') document.addEventListener('DOMContentLoaded', start);
else start();
